// Region measurements use the source image's normalized 0–100 coordinate space.
export type PartRegion =
  | readonly [width: number, height: number, angle: number, shape: 'oval' | 'box']
  | readonly (readonly [x: number, y: number])[];

export type ImageHotspot = {
  x: number;
  y: number;
  region: PartRegion;
  name: string;
  function: string;
  connection: string;
};

const point = (x: number, y: number, region: PartRegion, name: string, purpose: string, connection: string): ImageHotspot =>
  ({ x, y, region, name, function: purpose, connection });

